catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }

    var ga = new GlideAjax('TrainingRegistrationUtils');
    var userId = g_user_id; 
    var selectedDate = g_form.getValue('schedule_date');

    ga.addParam('sysparm_user_id', userId); 
    ga.addParam('sysparm_training_date', selectedDate); 
    ga.addParam('sysparm_name', 'getAvailableCourses');

    ga.getXML(function(response) {
        var answer = response.responseXML.documentElement.getAttribute('answer');
        var availableCourses = JSON.parse(answer); 

        var courseField = g_form.getControl('course'); 
        var options = availableCourses.map(function(course) {
            return {
                value: course.sys_id,
                label: course.course_name
            };
        });

        courseField.innerHTML = '';
        options.forEach(function(option) {
            var optionElement = document.createElement('option');
            optionElement.value = option.value;
            optionElement.textContent = option.label;
            courseField.appendChild(optionElement);
        });
    });
}
